/* Thermosys - Page "Validation et references" : correction de la limite chambre froide (le point de rosee sous 0 C est calcule sur la glace, comme CoolProp, ecart <= 0,01 K ; l ancienne mention "3,7 K" etait perimee). Met aussi a jour la ligne psychrometrie de tests\\README_TESTS.txt.
   Usage (depuis le dossier files) :  node patch_validation_page_v4.js */
'use strict';
const fs = require('fs'), path = require('path');
const file = process.argv[2] || path.join('dist', 'index.html');
if (!fs.existsSync(file)) { console.error('Fichier introuvable : ' + file); process.exit(2); }
const raw = fs.readFileSync(file, 'utf8'), crlf = raw.indexOf('\r\n') >= 0;
let s = crlf ? raw.replace(/\r\n/g, '\n') : raw;
const MOD = Buffer.from("", 'base64').toString('utf8');
const TEST = Buffer.from("", 'base64').toString('utf8');
function fixReadme() {
  const rd = path.join('tests', 'README_TESTS.txt'); if (!fs.existsSync(rd)) return;
  const c = fs.readFileSync(rd, 'utf8'), crl = c.indexOf('\r\n') >= 0; let r = crl ? c.replace(/\r\n/g, '\n') : c;
  const o = "chambre froide : point de rosee sur l'eau liquide quand il est sous 0 C (ecart jusqu'a 3,7 K).";
  const n = "chambre froide : sous 0 C le point de rosee est un point de givre (calcule sur la glace, comme CoolProp ; ecart <= 0,01 K controle de -30 a 5 C ; l'ancienne mention de 3,7 K etait perimee).";
  if (r.indexOf(o) >= 0) { r = r.replace(o, n); fs.writeFileSync(rd, crl ? r.replace(/\n/g, '\r\n') : r, 'utf8'); }
}
function writeTest() {
  fixReadme();
  fs.mkdirSync('tests', { recursive: true }); fs.writeFileSync(path.join('tests', 'validation_regression.js'), TEST, 'utf8');
  const rd = path.join('tests', 'README_TESTS.txt'); let r = fs.existsSync(rd) ? fs.readFileSync(rd, 'utf8') : '';
  if (r.indexOf('validation_regression.js') < 0) fs.writeFileSync(rd, r + (r && !/\n$/.test(r) ? '\n' : '') + '\nvalidation_regression.js : page Validation et references (contenu, trois langues, absence de chiffre non mesure) : verifications automatiques. Commande : node tests\\validation_regression.js\n', 'utf8');
}
if (s.indexOf('THERMOSYS_VALIDATION_V4') >= 0) { writeTest(); console.log('Deja applique : test reecrit.'); process.exit(0); }
const open = '<script id="validation-46-module">', a = s.indexOf(open);
if (a < 0) { console.error('ECHEC : appliquer d\'abord patch_validation_page_v1.js. Fichier non modifie.'); process.exit(3); }
if (s.indexOf(open, a + 1) >= 0) { console.error('ECHEC : module validation-46 en double. Fichier non modifie.'); process.exit(3); }
const e = s.indexOf('</script>', a);
if (e < 0) { console.error('ECHEC : fin du module validation-46 introuvable.'); process.exit(3); }
s = s.slice(0, a) + open + '\n' + MOD + s.slice(e);
fs.writeFileSync(file, crlf ? s.replace(/\n/g, '\r\n') : s, 'utf8');
writeTest();
console.log('OK : page Validation mise a jour.');
